```go
// CrudRepo đã implement sẵn GetList
// Hoặc override nếu cần custom query:

func (r *ProductRepo) GetList(ctx context.Context, req _dto.IPagable) ([]*domain.Product, int64, error) {
    var products []*domain.Product
    var total int64

    query := r.Db.WithContext(ctx).Model(&domain.Product{})

    // Apply filters
    if req.ProvinceId != nil {
        query = query.Where("province_id = ?", *req.ProvinceId)
    }

    // Count total
    query.Count(&total)

    // Apply pagination
    offset := req.GetOffset()
    limit := req.GetLimit()
    query = query.Offset(offset).Limit(limit)

    // Execute
    if err := query.Find(&products).Error; err != nil {
        return nil, 0, err
    }

    return products, total, nil
}
```

**Response format**:
```json
{
  "data": [
    {"id": 1, "name": "Nhà mặt tiền Quận 1", ...},
    {"id": 2, "name": "Căn hộ Vinhomes", ...}
  ],
  "total": 150
}
```

**Key points**:
- Request DTO embed `_dto.Pagable`
- Response LUÔN trả `data` (array) + `total` (int64)
- Repository dùng `GetOffset()` và `GetLimit()` từ Pagable
- Default: page=1, size=20, max size=100

